    String commitTime = "000";
    client.startCommitWithTime(commitTime);
    HoodieTestDataGenerator dataGen = new HoodieTestDataGenerator();
    List<HoodieRecord> records = dataGen.generateInserts(commitTime, 200);
    JavaRDD<HoodieRecord> writeRecords = jsc.parallelize(records, 1);
    JavaRDD<WriteStatus> statuses = client.insert(writeRecords, commitTime);
    assertTrue("Commit should succeed", client.commit(commitTime, statuses));
    // Read from commit file
    table = HoodieTable.getHoodieTable(metaClient, cfg, jsc);
    HoodieCommitMetadata metadata = HoodieCommitMetadata.fromBytes(table.getActiveTimeline().getInstantDetails(table.getActiveTimeline().getDeltaCommitTimeline().lastInstant().get()).get(), HoodieCommitMetadata.class);
    HoodieRollingStatMetadata rollingStatMetadata = HoodieCommitMetadata.fromBytes(metadata.getExtraMetadata().get(HoodieRollingStatMetadata.ROLLING_STAT_METADATA_KEY).getBytes(), HoodieRollingStatMetadata.class);
    int inserts = 0;
    for (Map.Entry<String, Map<String, HoodieRollingStat>> pstat : rollingStatMetadata.getPartitionToRollingStats().entrySet()) {
        for (Map.Entry<String, HoodieRollingStat> stat : pstat.getValue().entrySet()) {
            inserts += stat.getValue().getInserts();
            fileIdToInsertsMap.put(stat.getKey(), stat.getValue().getInserts());
            fileIdToUpsertsMap.put(stat.getKey(), stat.getValue().getUpserts());
        }
    }
    Assert.assertEquals(inserts, 200);
    commitTime = "001";
    client.startCommitWithTime(commitTime);
    // generate updates + inserts. inserts should be handled into small files
    records = dataGen.generateUpdates(commitTime, records);
    records.addAll(dataGen.generateInserts(commitTime, 200));
    writeRecords = jsc.parallelize(records, 1);
    statuses = client.upsert(writeRecords, commitTime);
    assertTrue("Commit should succeed", client.commit(commitTime, statuses));
    // Read from commit file
    table = HoodieTable.getHoodieTable(metaClient, cfg, jsc);
    metadata = HoodieCommitMetadata.fromBytes(table.getActiveTimeline().getInstantDetails(table.getActiveTimeline().getDeltaCommitTimeline().lastInstant().get()).get(), HoodieCommitMetadata.class);
    rollingStatMetadata = HoodieCommitMetadata.fromBytes(metadata.getExtraMetadata().get(HoodieRollingStatMetadata.ROLLING_STAT_METADATA_KEY).getBytes(), HoodieRollingStatMetadata.class);
    inserts = 0;
    int upserts = 0;
    for (Map.Entry<String, Map<String, HoodieRollingStat>> pstat : rollingStatMetadata.getPartitionToRollingStats().entrySet()) {
        for (Map.Entry<String, HoodieRollingStat> stat : pstat.getValue().entrySet()) {
            // No new file id should be created, all the data should be written to small files already there
            assertTrue(fileIdToInsertsMap.containsKey(stat.getKey()));
            assertTrue(fileIdToUpsertsMap.containsKey(stat.getKey()));
            inserts += stat.getValue().getInserts();
            upserts += stat.getValue().getUpserts();
        }
    }
    Assert.assertEquals(inserts, 400);
    Assert.assertEquals(upserts, 200);
    // Test small file handling after compaction
    commitTime = "002";
    client.scheduleCompactionAtInstant(commitTime, Optional.of(metadata.getExtraMetadata()));
    statuses = client.compact(commitTime);
    client.commitCompaction(commitTime, statuses, Optional.empty());
    // Read from commit file
    table = HoodieTable.getHoodieTable(metaClient, cfg, jsc);
    metadata = HoodieCommitMetadata.fromBytes(table.getActiveTimeline().getInstantDetails(table.getActiveTimeline().getCommitsTimeline().lastInstant().get()).get(), HoodieCommitMetadata.class);
    HoodieRollingStatMetadata rollingStatMetadata1 = HoodieCommitMetadata.fromBytes(metadata.getExtraMetadata().get(HoodieRollingStatMetadata.ROLLING_STAT_METADATA_KEY).getBytes(), HoodieRollingStatMetadata.class);
    // Ensure that the rolling stats from the extra metadata of delta commits is copied over to the compaction commit
    for (Map.Entry<String, Map<String, HoodieRollingStat>> entry : rollingStatMetadata.getPartitionToRollingStats().entrySet()) {
        Assert.assertTrue(rollingStatMetadata1.getPartitionToRollingStats().containsKey(entry.getKey()));
        Assert.assertEquals(rollingStatMetadata1.getPartitionToRollingStats().get(entry.getKey()).size(), entry.getValue().size());
    }
    // Write inserts + updates
    commitTime = "003";
    client.startCommitWithTime(commitTime);
    // generate updates + inserts. inserts should be handled into small files
    records = dataGen.generateUpdates(commitTime, records);
    records.addAll(dataGen.generateInserts(commitTime, 200));
    writeRecords = jsc.parallelize(records, 1);
    statuses = client.upsert(writeRecords, commitTime);
    assertTrue("Commit should succeed", client.commit(commitTime, statuses));
    // Read from commit file
    table = HoodieTable.getHoodieTable(metaClient, cfg, jsc);
    metadata = HoodieCommitMetadata.fromBytes(table.getActiveTimeline().getInstantDetails(table.getActiveTimeline().getDeltaCommitTimeline().lastInstant().get()).get(), HoodieCommitMetadata.class);
    rollingStatMetadata = HoodieCommitMetadata.fromBytes(metadata.getExtraMetadata().get(HoodieRollingStatMetadata.ROLLING_STAT_METADATA_KEY).getBytes(), HoodieRollingStatMetadata.class);
    inserts = 0;
    upserts = 0;
    for (Map.Entry<String, Map<String, HoodieRollingStat>> pstat : rollingStatMetadata.getPartitionToRollingStats().entrySet()) {
        for (Map.Entry<String, HoodieRollingStat> stat : pstat.getValue().entrySet()) {
            // No new file id should be created, all the data should be written to small files already there
            assertTrue(fileIdToInsertsMap.containsKey(stat.getKey()));
            inserts += stat.getValue().getInserts();
            upserts += stat.getValue().getUpserts();
        }
    }
    Assert.assertEquals(inserts, 600);
    Assert.assertEquals(upserts, 600);
