    assertTrue(HoodieTestUtils.doesDataFileExist(basePath, "2016/05/01", commitTime1, file11) && HoodieTestUtils.doesDataFileExist(basePath, "2016/05/02", commitTime1, file12) && HoodieTestUtils.doesDataFileExist(basePath, "2016/05/06", commitTime1, file13));
