    assertFalse(HoodieTestUtils.doesDataFileExist(basePath, "2016/05/01", commitTime2, file21) || HoodieTestUtils.doesDataFileExist(basePath, "2016/05/02", commitTime2, file22) || HoodieTestUtils.doesDataFileExist(basePath, "2016/05/06", commitTime2, file23));
